/**
 * Builds the final HTTP redirect responses for the OIDC authorization flow.
 *
 * Responsibilities: - Build the success redirect (authorization code or implicit token) after
 * authentication. - Build the error redirect with a fragment error parameter.
 *
 * Design notes: - Persists or updates the authenticated session via {@link SessionStoreGateway}. -
 * Registers the temporal auth code via {@link TemporalKeysGateway} for the code flow. - Sets the
 * {@code AUTH_SESSION_ID} cookie on success via {@link OidcCookieManager}.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class OidcResponseBuilder {

  private final SecureHtmlBuilder securer;
  private final SessionStoreGateway sessionStore;
  private final TemporalKeysGateway temporalStore;
  private final JwtTokenBuilder tokenBuilder;
  private final OidcCookieManager cookieManager;
  private final TenantQueryRepositoryGateway tenantRepo;
  private final TenantConfigQueryRepositoryGateway tenantConfigs;
  private final ClaimsMapper claimsMapper;
  private final SessionStateService sessionStates;
  private final TokenSigner tokenSigner;
  private final UserClaimsGateway userClaims;
  private static final SecureRandom RANDOM = new SecureRandom();

  /**
   * Builds a redirect response after successful authentication.
   *
   * <p>
   * When {@code existingSession} is present the session is updated in place; otherwise a new
   * session is created using the {@code csid} from the form params.
   *
   * @param existingSession existing AUTH_SESSION_ID value, or empty for a new session
   * @param clientDetails authenticated client
   * @param grant grant type label (e.g. {@code "form"})
   * @param request current auth request
   * @param validationData authenticated user data
   * @param paramMap form parameters (needed for {@code csid} on new sessions)
   * @return 302 redirect response with the auth code or token fragment
   */
  public Response successRedirect(Optional<String> existingSession, ClientDetails clientDetails,
      String grant, AuthRequest request, AuthenticationData validationData,
      MultivaluedMap<String, String> paramMap) {
    String type = request.getResponseType().orElse("code");
    if (List.of(type.split(" ")).contains("id_token")
        && request.getNonce().filter(n -> !n.isBlank()).isEmpty()) {
      return errorRedirect(request, "invalid_request");
    }
    // The login may have granted its own scopes (root tenant): they are added, not a replacement.
    List<String> requested = Arrays.stream(request.getScope().orElse("").split("\\s+"))
        .filter(scope -> !scope.isBlank()).toList();
    validationData.setScopes(clientDetails.grantableScopes(requested, validationData.getScopes()));
    if (List.of(type.split(" ")).contains("id_token")
        && !validationData.getScopes().contains("openid")) {
      return errorRedirect(request, "invalid_scope");
    }
    Optional<String> missing = missingEssentialClaim(request, validationData);
    if (missing.isPresent()) {
      return errorRedirect(request, "access_denied",
          "The essential claim " + missing.get() + " is not available for this user");
    }
    if ("code".equals(type)) {
      if (clientDetails.isRequirePkce() && request.getCodeChallenge().isEmpty()) {
        return errorRedirect(request, "invalid_request");
      }
      if ("plain".equals(request.getCodeChallengeMethod().orElse(""))) {
        return errorRedirect(request, "invalid_request");
      }
    }
    validationData.setAudiences(request.getAudiences());
    String uid = UUID.randomUUID().toString();
    if (existingSession.isPresent()) {
      sessionStore.updateSession(uid, existingSession.get());
    } else {
      String csid = securer.verifyToken(first(paramMap, "csid")).orElseThrow();
      sessionStore.saveSession(uid, clientDetails, grant, validationData, csid);
    }
    String sessionState = sessionStates.create(clientDetails.getClientId(),
        request.getRedirect().orElseThrow(), validationData.getSid());
    String to;
    if ("code".equals(type)) {
      String redirectUri = request.getRedirect().orElseThrow();
      String separator = "fragment".equals(request.getResponseMode().orElse("")) ? "#"
          : redirectUri.endsWith("?") ? "" : redirectUri.contains("?") ? "&" : "?";
      String code = temporalStore.registerTemporalAuthCode(
          TemporalAuthCode.builder().client(clientDetails).request(request)
              .nonce(request.getNonce().orElse(null)).data(validationData).sessionId(uid).build());
      to = redirectUri + separator + "code=" + encode(code) + stateParam(request) + "&iss="
          + encode(claimsMapper.issuer(request.getTenant())) + "&session_state="
          + encode(sessionState);
    } else {
      boolean hybrid = type.contains("code");
      String authCode = null;
      if (hybrid) {
        authCode = temporalStore.registerTemporalAuthCode(TemporalAuthCode.builder()
            .client(clientDetails).request(request).nonce(request.getNonce().orElse(null))
            .data(validationData).sessionId(uid).build());
      }
      boolean withId = List.of(type.split(" ")).contains("id_token");
      boolean withAccess = List.of(type.split(" ")).contains("token");
      IdToken buildIdToken =
          tokenBuilder.buildFrontChannelTokens(request.getTenant(), request.getNonce().orElse(null),
              clientDetails, grant, validationData, authCode, withAccess, withId);
      if (withAccess) {
        tokenBuilder.tokenJti(buildIdToken.getAccessToken(), request.getTenant())
            .ifPresent(jti -> sessionStore.updateTokenJtis(uid, clientDetails.getClientId(), jti,
                UUID.randomUUID().toString()));
      }
      StringBuilder fragment = new StringBuilder("#");
      if (authCode != null) {
        fragment.append("code=").append(encode(authCode));
      }
      fragment.append(stateParam(request));
      fragment.append("&iss=")
          .append(URLEncoder.encode(buildIdToken.getIss(), StandardCharsets.UTF_8));
      fragment.append("&session_state=").append(encode(sessionState));
      if (buildIdToken.getIdToken() != null) {
        fragment.append("&id_token=").append(buildIdToken.getIdToken());
      }
      if (withAccess) {
        fragment.append("&access_token=").append(encode(buildIdToken.getAccessToken()))
            .append("&token_type=Bearer&expires_in=").append(buildIdToken.getExpiresIn());
      }
      to = request.getRedirect().orElseThrow() + fragment.toString().replace("#&", "#");
    }
    NewCookie cookie =
        cookieManager.writeAuthSession(uid, request.getTenant(), ssoTtl(request.getTenant()));
    Optional<String> jarm = jarmMode(request);
    if (jarm.isPresent()) {
      return jarm(request, to, jarm.get(), cookie);
    }
    if ("form_post".equals(request.getResponseMode().orElse(""))) {
      return formPost(request.getRedirect().orElseThrow(), to, cookie);
    }
    return securer.secureRedirectResponse(
        Response.status(302).location(AuthorizeHtml.buildUrl(to)).cookie(cookie));
  }

  /**
   * Builds an error redirect response with a {@code #error=} fragment.
   *
   * @param request the current auth request (used for redirect URI and tenant)
   * @param message the error description to include in the fragment
   * @return 302 redirect response with cleared AUTH_SESSION_ID cookie
   */
  public Response errorRedirect(AuthRequest request, String message) {
    return errorRedirect(request, message, null);
  }

  public Response errorRedirect(AuthRequest request, String message, String description) {
    if (request.getRedirect().isEmpty()) {
      return Response.status(400).entity(Map.of("error", message, "error_description",
          description == null ? message : description)).build();
    }
    String redirect = request.getRedirect().get();
    boolean fragment = !"code".equals(request.getResponseType().orElse("code"))
        || "fragment".equals(request.getResponseMode().orElse(""));
    Optional<String> jarm = jarmMode(request);
    String separator = fragment ? "#" : redirect.contains("?") ? "&" : "?";
    String to = redirect + separator + "error=" + encode(message) + "&error_description="
        + encode(description == null ? message : description) + stateParam(request) + "&iss="
        + encode(claimsMapper.issuer(request.getTenant()));
    if (jarm.isPresent()) {
      return jarm(request, to, jarm.get(), null);
    }
    if ("form_post".equals(request.getResponseMode().orElse(""))) {
      return formPost(redirect, to, null);
    }
    return securer
        .secureRedirectResponse(Response.status(302).location(AuthorizeHtml.buildUrl(to)));
  }

  /**
   * An essential claim of the {@code claims} parameter that the user does not have with the granted
   * scopes (task 4.8): the request ends before any code or token is issued.
   */
  private Optional<String> missingEssentialClaim(AuthRequest request, AuthenticationData data) {
    try {
      return ClaimsRequest.parse(request.getClaims().orElse(null))
          .flatMap(claims -> claims.essentialMissing(
              userClaims.claims(data.getUid(), data.getUsername(), data.getScopes()).entrySet()
                  .stream().filter(e -> e.getValue() != null).map(Map.Entry::getKey).toList()));
    } catch (IllegalArgumentException ex) {
      return Optional.empty();
    }
  }

  /**
   * The JWT secured mode of the request (JARM, task 4.2): {@code jwt} is {@code query.jwt} for a
   * code and {@code fragment.jwt} when tokens are returned.
   */
  private static Optional<String> jarmMode(AuthRequest request) {
    String mode = request.getResponseMode().orElse("");
    if ("jwt".equals(mode)) {
      return Optional.of(
          "code".equals(request.getResponseType().orElse("code")) ? "query.jwt" : "fragment.jwt");
    }
    return mode.endsWith(".jwt") ? Optional.of(mode) : Optional.empty();
  }

  /**
   * Delivers the parameters of a response as a single {@code response} JWT signed by the server,
   * with {@code iss}, {@code aud} (the client) and a 10 minute {@code exp}, in the query, the
   * fragment or a form post.
   */
  private Response jarm(AuthRequest request, String location, String mode, NewCookie cookie) {
    String redirect = request.getRedirect().orElseThrow();
    Map<String, Object> params = new LinkedHashMap<>(parameters(redirect, location));
    params.remove("iss");
    String response = tokenSigner.sign(request.getTenant(),
        JWT.create().withPayload(params).withIssuer(claimsMapper.issuer(request.getTenant()))
            .withAudience(request.getClientId().orElse("")).withIssuedAt(new java.util.Date()),
        java.time.Instant.now().plus(java.time.Duration.ofMinutes(10)));
    if ("form_post.jwt".equals(mode)) {
      return formPost(redirect, redirect + "?response=" + response, cookie);
    }
    String to = "fragment.jwt".equals(mode) ? redirect + "#response=" + response
        : redirect + (redirect.contains("?") ? "&" : "?") + "response=" + response;
    Response.ResponseBuilder builder = Response.status(302).location(AuthorizeHtml.buildUrl(to));
    if (cookie != null) {
      builder.cookie(cookie);
    }
    return securer.secureRedirectResponse(builder);
  }

  private static Map<String, String> parameters(String redirect, String location) {
    String suffix = location.substring(redirect.length());
    if (!suffix.isEmpty())
      suffix = suffix.substring(1);
    Map<String, String> fields = new LinkedHashMap<>();
    for (String pair : suffix.split("&")) {
      int equals = pair.indexOf('=');
      if (equals > 0) {
        fields.put(URLDecoder.decode(pair.substring(0, equals), StandardCharsets.UTF_8),
            URLDecoder.decode(pair.substring(equals + 1), StandardCharsets.UTF_8));
      }
    }
    return fields;
  }

  private Response formPost(String redirect, String location, NewCookie cookie) {
    String suffix = location.substring(redirect.length());
    if (!suffix.isEmpty())
      suffix = suffix.substring(1);
    Map<String, String> fields = new LinkedHashMap<>();
    for (String pair : suffix.split("&")) {
      int equals = pair.indexOf('=');
      if (equals > 0) {
        fields.put(URLDecoder.decode(pair.substring(0, equals), StandardCharsets.UTF_8),
            URLDecoder.decode(pair.substring(equals + 1), StandardCharsets.UTF_8));
      }
    }
    byte[] random = new byte[24];
    RANDOM.nextBytes(random);
    String nonce = Base64.getUrlEncoder().withoutPadding().encodeToString(random);
    StringBuilder html =
        new StringBuilder("<!doctype html><html><head><meta charset=\"utf-8\"></head>"
            + "<body><form id=\"oidc-response\" method=\"post\" action=\"").append(escape(redirect))
                .append("\">");
    fields.forEach((name, value) -> html.append("<input type=\"hidden\" name=\"")
        .append(escape(name)).append("\" value=\"").append(escape(value)).append("\">"));
    html.append("<noscript><button type=\"submit\">Continue</button></noscript></form>")
        .append("<script nonce=\"").append(nonce)
        .append("\">document.getElementById('oidc-response').submit();</script></body></html>");
    URI action = AuthorizeHtml.buildUrl(redirect);
    String origin = action.getScheme() + "://" + action.getRawAuthority();
    Response.ResponseBuilder response = Response.ok(html.toString()).type("text/html;charset=UTF-8")
        .header("Cache-Control", "no-store").header("Pragma", "no-cache")
        .header("Referrer-Policy", "no-referrer").header("X-Content-Type-Options", "nosniff")
        .header("Content-Security-Policy", "default-src 'none'; script-src 'nonce-" + nonce
            + "'; form-action " + origin + "; base-uri 'none'; frame-ancestors 'none'");
    if (cookie != null)
      response.cookie(cookie);
    return response.build();
  }

  private static String escape(String value) {
    return value.replace("&", "&amp;").replace("\"", "&quot;").replace("'", "&#39;")
        .replace("<", "&lt;").replace(">", "&gt;");
  }

  private static String encode(String value) {
    return URLEncoder.encode(value, StandardCharsets.UTF_8);
  }

  /**
   * {@code &state=...} encoded, so reserved characters come back intact; nothing without state
   * (task 0.11).
   */
  private static String stateParam(AuthRequest request) {
    return request.getState().filter(state -> !state.isEmpty())
        .map(state -> "&state=" + URLEncoder.encode(state, StandardCharsets.UTF_8)).orElse("");
  }

  private int ssoTtl(String tenantName) {
    return tenantRepo.find(TenantFilter.builder().name(tenantName).build())
        .flatMap(t -> tenantConfigs.find(TenantConfigFilter.builder().tenant(t).build()))
        .map(cfg -> cfg.getSessionSsoTtlSeconds()).orElse(3600);
  }

  private static String first(Map<String, List<String>> paramMap, String key) {
    List<String> list = paramMap.get(key);
    return null == list || list.isEmpty() ? "" : list.get(0);
  }
}
